import { escapeHtml } from "src/escape-html";
import { findLineIndexOfSearchStringIgnoringWs } from "src/utils/strings";

export interface MultipleChoiceOption {
    text: string;
    isCorrect: boolean;
}

export interface MultipleChoiceCardData {
    question: string;
    options: MultipleChoiceOption[];
    correctOption: MultipleChoiceOption;
    hint: string | null;
}

const multipleChoiceOptionRegex = /^\s*-\s+\[( |x|X)\]\s+(.+)$/;
const hintPrefix = "Dica:";

export function getMultipleChoiceFallbackHint(correctOptionText: string): string {
    return `Resposta correta: ${correctOptionText}`;
}

export function parseMultipleChoiceQuestion(
    questionText: string,
    separator: string,
): MultipleChoiceCardData | null {
    if (!separator) return null;

    const questionLines = questionText.split("\n");
    const separatorLineIdx = findLineIndexOfSearchStringIgnoringWs(questionLines, separator);
    if (separatorLineIdx < 0) return null;

    const question = questionLines.slice(0, separatorLineIdx).join("\n").trimEnd();
    if (question.trim().length === 0) return null;

    const optionLines = questionLines.slice(separatorLineIdx + 1);
    const options: MultipleChoiceOption[] = [];
    let hint: string | null = null;
    let foundHint = false;

    for (const line of optionLines) {
        const trimmedLine = line.trim();
        if (trimmedLine.length === 0) return null;

        if (trimmedLine.startsWith(hintPrefix)) {
            if (foundHint) return null;
            foundHint = true;
            const hintText = trimmedLine.substring(hintPrefix.length).trim();
            hint = hintText.length > 0 ? hintText : null;
            continue;
        }

        if (foundHint) return null;

        const match = line.match(multipleChoiceOptionRegex);
        if (!match) return null;

        const optionText = match[2].trim();
        if (optionText.length === 0) return null;

        options.push({
            text: optionText,
            isCorrect: match[1] === "x" || match[1] === "X",
        });
    }

    if (options.length < 2 || options.length > 4) return null;

    const correctOptions = options.filter((option) => option.isCorrect);
    if (correctOptions.length !== 1) return null;

    return {
        question,
        options,
        correctOption: correctOptions[0],
        hint,
    };
}

export function formatMultipleChoiceFront(card: MultipleChoiceCardData): string {
    const fallbackHint = getMultipleChoiceFallbackHint(card.correctOption.text);
    const feedbackText = card.hint ?? fallbackHint;
    const optionsHtml = card.options
        .map(
            (option, index) =>
                `<button type="button" class="sr-multiple-choice-option" data-index="${index}" data-correct="${option.isCorrect ? "true" : "false"}">${escapeHtml(option.text)}</button>`,
        )
        .join("\n");

    return `${card.question}

<div class="sr-multiple-choice-card" data-answer="${escapeHtml(card.correctOption.text)}" data-hint="${escapeHtml(feedbackText)}">
<div class="sr-multiple-choice-options">
${optionsHtml}
</div>
<div class="sr-multiple-choice-feedback" aria-live="polite"></div>
</div>`;
}

export function formatMultipleChoiceBack(card: MultipleChoiceCardData): string {
    const backLines = [getMultipleChoiceFallbackHint(card.correctOption.text)];
    if (card.hint) backLines.push("", `${hintPrefix} ${card.hint}`);
    return backLines.join("\n");
}

